package model;

import java.io.Serializable;
import java.util.Date;

/**
 * Simple model for a password reset token.
 * Backed by an Oracle table, for example:
 *
 * CREATE TABLE password_reset_tokens (
 *   id           NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 *   user_id      NUMBER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 *   token_hash   VARCHAR2(128) NOT NULL,
 *   expires_at   TIMESTAMP NOT NULL,
 *   used         NUMBER(1) DEFAULT 0 NOT NULL
 * );
 *
 * CREATE INDEX idx_prt_token_hash ON password_reset_tokens(token_hash);
 */
public class PasswordResetToken implements Serializable {
    private static final long serialVersionUID = 1L;

    private int id;
    private int userId;
    private String tokenHash;
    private Date expiresAt;
    private boolean used;

    public int getId() { return id; }
    public void setId(int id) { this.id = id; }

    public int getUserId() { return userId; }
    public void setUserId(int userId) { this.userId = userId; }

    public String getTokenHash() { return tokenHash; }
    public void setTokenHash(String tokenHash) { this.tokenHash = tokenHash; }

    public Date getExpiresAt() { return expiresAt; }
    public void setExpiresAt(Date expiresAt) { this.expiresAt = expiresAt; }

    public boolean isUsed() { return used; }
    public void setUsed(boolean used) { this.used = used; }
}

